import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"🗃️ 02 · 向量数据库与 RAG 工程","description":"","frontmatter":{},"headers":[],"relativePath":"08-AI应用开发/02-向量数据库与RAG工程.md","filePath":"08-AI应用开发/02-向量数据库与RAG工程.md","lastUpdated":1786806808000}'),l={name:"08-AI应用开发/02-向量数据库与RAG工程.md"};function n(d,t,s,i,g,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="🗃️-02-·-向量数据库与-rag-工程" tabindex="-1">🗃️ 02 · 向量数据库与 RAG 工程 <a class="header-anchor" href="#🗃️-02-·-向量数据库与-rag-工程" aria-label="Permalink to &quot;🗃️ 02 · 向量数据库与 RAG 工程&quot;">​</a></h1><blockquote><p>RAG 落地的「工程心脏」是向量库。选型、索引、性能、成本直接决定效果与体验。详见 <code>03-AI Agent/02-RAG</code> 原理，本篇讲工程实现。</p></blockquote><hr><h2 id="一、主流向量库对比" tabindex="-1">一、主流向量库对比 <a class="header-anchor" href="#一、主流向量库对比" aria-label="Permalink to &quot;一、主流向量库对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>向量库</th><th>特点</th><th>适用</th></tr></thead><tbody><tr><td><strong>Milvus</strong></td><td>分布式、企业级、功能全</td><td>大规模生产</td></tr><tr><td><strong>pgvector</strong></td><td>PG 插件，复用关系库</td><td>中小规模、少运维</td></tr><tr><td><strong>FAISS</strong></td><td>高性能单机库（Meta）</td><td>嵌入应用/原型</td></tr><tr><td><strong>Qdrant / Weaviate</strong></td><td>云原生、易用</td><td>中等规模</td></tr><tr><td><strong>Redis / Elasticsearch</strong></td><td>已有则复用</td><td>轻量/全文本+向量</td></tr></tbody></table><h2 id="二、索引与检索" tabindex="-1">二、索引与检索 <a class="header-anchor" href="#二、索引与检索" aria-label="Permalink to &quot;二、索引与检索&quot;">​</a></h2><ul><li><strong>ANN 索引</strong>：HNSW（图，快、内存大）、IVF（倒排，省内存）、PQ（量化压缩）</li><li><strong>距离度量</strong>：余弦（最常用）、内积、欧氏</li><li><strong>维度</strong>：embedding 通常 768/1024/1536 维</li><li><strong>混合检索</strong>：向量（语义）+ BM25（关键词）→ RRF 融合，效果最佳</li></ul><h2 id="三、工程要点" tabindex="-1">三、工程要点 <a class="header-anchor" href="#三、工程要点" aria-label="Permalink to &quot;三、工程要点&quot;">​</a></h2><ul><li><strong>分块策略</strong>：按语义/标题切，overlap 防断义；块大小影响召回与噪声</li><li><strong>元数据过滤</strong>：先按时间/来源/权限过滤再检索（降本提准）</li><li><strong>写入/更新</strong>：文档变更要增量更新向量，避免全量重建</li><li><strong>一致性</strong>：多租户隔离（见 <code>07-后端</code>）</li><li><strong>性能</strong>：批量嵌入、异步入库、缓存热点查询</li></ul><h2 id="四、rag-质量调优清单" tabindex="-1">四、RAG 质量调优清单 <a class="header-anchor" href="#四、rag-质量调优清单" aria-label="Permalink to &quot;四、RAG 质量调优清单&quot;">​</a></h2><ul><li>[ ] 召回率够吗？（换 embedding / 加 BM25 / 调 top-k）</li><li>[ ] 排序准吗？（加重排 rerank）</li><li>[ ] 上下文噪声？（压缩/筛选相关句）</li><li>[ ] 忠实度？（要求仅基于片段、给引用）</li><li>[ ] 端到端评测？（RAGAS：faithfulness/context recall/answer relevancy）</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：HNSW 和 IVF 怎么选？</strong></p><blockquote><p>HNSW 查询快但内存占用大，适合追求低延迟；IVF 省内存、可扩展到超大库，适合成本敏感/超大规模。常配合 PQ 压缩。</p></blockquote><p><strong>Q2：为什么需要混合检索？</strong></p><blockquote><p>向量擅长语义、弱于精确关键词（如专有名词/编号）；BM25 擅长精确匹配。融合互补，显著提升召回质量。</p></blockquote><p><strong>Q3：向量库数据怎么和源文档保持一致？</strong></p><blockquote><p>文档变更触发增量重新嵌入与 upsert，旧向量删除；用版本/etag 追踪；定期全量校验，避免脏数据。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-Agent工程实践">03-Agent工程实践</a></p>',20)])])}const p=r(l,[["render",n]]);export{u as __pageData,p as default};
